import fs from "node:fs/promises";
import path from "node:path";
import util from "node:util";
import { getCommitInfo, getPullRequestInfo } from "@changesets/get-github-info";
//#region src/render-template.ts
const TOKEN_REGEX = /\{(\w+)\}/g;
const RELEASE_LINE_TOKENS = [
	"summary",
	"ref",
	"pull",
	"commit",
	"authors"
];
function renderTemplate(template, tokens) {
	return template.replace(TOKEN_REGEX, (_match, name) => {
		if (!Object.hasOwn(tokens, name)) throw new Error(`Unknown changelog template token "{${name}}". Valid tokens are: ${RELEASE_LINE_TOKENS.map((t) => `{${t}}`).join(", ")}.`);
		return tokens[name];
	});
}
function buildReleaseLineTokens(args) {
	const { summaryLinked, links, users } = args;
	return {
		summary: summaryLinked,
		ref: links.pull ? `(${links.pull})` : links.commit ? `(${links.commit})` : "",
		pull: links.pull ?? "",
		commit: links.commit ?? "",
		authors: users ?? ""
	};
}
//#endregion
//#region src/index.ts
const ISSUE_REF_REGEX = /\[.*?\]\(.*?\)|\B#([1-9]\d*)\b/g;
function linkifyIssueRefs(line, { serverUrl, repo }) {
	return line.replace(ISSUE_REF_REGEX, (match, issue) => issue ? `[#${issue}](${serverUrl}/${repo}/issues/${issue})` : match);
}
async function readEnvFile() {
	const envFile = path.resolve(process.cwd(), ".env");
	let content;
	try {
		content = await fs.readFile(envFile, "utf-8");
	} catch {
		return {};
	}
	return util.parseEnv(content);
}
let cachedEnv;
function readEnvFileCached() {
	cachedEnv ??= readEnvFile();
	return cachedEnv;
}
async function readEnv() {
	return {
		GITHUB_SERVER_URL: process.env.GITHUB_SERVER_URL || (await readEnvFileCached()).GITHUB_SERVER_URL || "https://github.com",
		GITHUB_REPOSITORY: process.env.GITHUB_REPOSITORY || (await readEnvFileCached()).GITHUB_REPOSITORY
	};
}
async function getRepo(options) {
	let repo;
	if (options && "repo" in options) repo = typeof options.repo === "string" && options.repo ? options.repo : void 0;
	else repo = (await readEnv()).GITHUB_REPOSITORY;
	if (!repo) throw new Error("Please provide a repo to this changelog generator like this:\n\"changelog\": [\"@changesets/changelog-github\", { \"repo\": \"org/repo\" }]\nor set the GITHUB_REPOSITORY environment variable.");
	return repo;
}
const changelogFunctions = {
	getDependencyReleaseLine: async (changesets, dependenciesUpdated, options) => {
		const repo = await getRepo(options);
		if (dependenciesUpdated.length === 0) return "";
		return [`- Updated dependencies [${(await Promise.all(changesets.map(async (cs) => {
			if (cs.commit) return (await getCommitInfo({
				commit: cs.commit,
				repo
			}))?.commit.markdownLink ?? `\`${cs.commit.slice(0, 7)}\``;
		}))).filter((_) => _).join(", ")}]:`, ...dependenciesUpdated.map((dependency) => `  - ${dependency.name}@${dependency.newVersion}`)].join("\n");
	},
	getReleaseLine: async (changeset, type, options) => {
		const repo = await getRepo(options);
		const { GITHUB_SERVER_URL } = await readEnv();
		let prFromSummary;
		let commitFromSummary;
		const usersFromSummary = [];
		const [firstLine, ...futureLines] = changeset.summary.replace(/^\s*(?:pr|pull|pull\s+request):\s*#?(\d+)/im, (_, pr) => {
			const num = Number(pr);
			if (!isNaN(num)) prFromSummary = num;
			return "";
		}).replace(/^\s*commit:\s*([^\s]+)/im, (_, commit) => {
			commitFromSummary = commit;
			return "";
		}).replace(/^\s*(?:author|user):\s*@?([^\s]+)/gim, (_, user) => {
			usersFromSummary.push(user);
			return "";
		}).trim().split("\n").map((l) => l.trimEnd());
		const links = {
			commit: void 0,
			pull: void 0,
			user: void 0
		};
		if (prFromSummary != null) {
			const info = await getPullRequestInfo({
				pull: prFromSummary,
				repo
			});
			links.commit = info?.commit?.markdownLink;
			links.pull = info?.pull.markdownLink;
			links.user = info?.author?.markdownLink;
			if (commitFromSummary) {
				const url = `${GITHUB_SERVER_URL}/${repo}/commit/${commitFromSummary}`;
				links.commit = `[\`${commitFromSummary.slice(0, 7)}\`](${url})`;
			}
		} else if (commitFromSummary || changeset.commit) {
			const info = await getCommitInfo({
				commit: commitFromSummary || changeset.commit,
				repo
			});
			links.commit = info?.commit.markdownLink;
			links.pull = info?.pull?.markdownLink;
			links.user = info?.author?.markdownLink;
		}
		const users = options?.disableThanks ? null : usersFromSummary.length ? usersFromSummary.map((userFromSummary) => `[@${userFromSummary}](${GITHUB_SERVER_URL}/${userFromSummary})`).join(", ") : links.user;
		const linkOpts = {
			serverUrl: GITHUB_SERVER_URL,
			repo
		};
		const summaryLinked = linkifyIssueRefs(firstLine, linkOpts);
		const continuation = futureLines.map((l) => `  ${linkifyIssueRefs(l, linkOpts)}`).join("\n");
		if (typeof options?.template === "string" && options.template.length > 0) {
			const tokens = buildReleaseLineTokens({
				summaryLinked,
				links,
				users
			});
			return `${renderTemplate(options.template, tokens).trimEnd()}\n${continuation}`;
		}
		const prefix = [
			links.pull == null ? "" : ` ${links.pull}`,
			links.commit == null ? "" : ` ${links.commit}`,
			users == null ? "" : ` Thanks ${users}!`
		].join("");
		return `\n\n-${prefix ? `${prefix} -` : ""} ${summaryLinked}\n${continuation}`;
	}
};
//#endregion
export { changelogFunctions as default };
